import{_ as n,C as t,o as i,c as s,E as a,a2 as l}from"./chunks/framework.BdWD-ld-.js";const h="/joinwell52/assets/work-package-portability-20261128/inventory.en.mobile.svg",d="/joinwell52/assets/work-package-portability-20261128/inventory.en.svg",f=JSON.parse('{"title":"Can an AI worker check an equipment list without a terminal?","description":"One equipment-list assignment, three tool setups. A CodeFlowMu experiment traces what each AI worker could read and what it could hand back.","frontmatter":{"title":"Can an AI worker check an equipment list without a terminal?","description":"One equipment-list assignment, three tool setups. A CodeFlowMu experiment traces what each AI worker could read and what it could hand back.","cover":"/assets/covers/2026-11-28-work-package-portability.png","date":"2026-11-28","published_date":"2026-11-28","column":"digital-employee","category":"daily","article_type":"experiment-report","edition":"research-center","language":"en-US","lifecycle":"Published","publication_authorized":true,"lang":"en-US","pageClass":"six-governance-article"},"headers":[],"relativePath":"en/research/2026-11-28-work-package-portability.md","filePath":"en/research/2026-11-28-work-package-portability.md","lastUpdated":1795879845000}'),c={name:"en/research/2026-11-28-work-package-portability.md"},p=h;function u(m,e,w,g,k,b){const o=t("ArticleCover"),r=t("ArticleTableScroll");return i(),s("div",null,[a(o,{image:"/assets/covers/2026-11-28-work-package-portability.png",kicker:"Digital Employees · Work Packages",title:"Can an AI worker check an equipment list without a terminal?",summary:"One equipment-list assignment, three tool setups. A CodeFlowMu experiment traces what each AI worker could read and what it could hand back.",version:"2026-11-28",languageHref:"/zh/research/2026-11-28-work-package-portability",languageLabel:"简体中文"}),a(r,{language:"en"}),e[0]||(e[0]=l('<h1 id="can-an-ai-worker-check-an-equipment-list-without-a-terminal" tabindex="-1">Can an AI worker check an equipment list without a terminal? <a class="header-anchor" href="#can-an-ai-worker-check-an-equipment-list-without-a-terminal" aria-label="Permalink to &quot;Can an AI worker check an equipment list without a terminal?&quot;">​</a></h1><p>The storeroom register lists three equipment IDs: <code>D-01</code>, <code>D-02</code>, and <code>D-03</code>. You give an AI worker a simple assignment. Compare the register with the physical count and report which IDs are absent from the count sheet.</p><p>The worker can read the register. Its environment supplies neither a tool for reading the count sheet nor a terminal, the window where you enter commands and run programs. What can it confirm? What should it leave for follow-up? We ran the same assignment under three instruction and tool conditions to see what the worker actually handed back.</p><h2 id="how-far-can-the-same-instructions-travel" tabindex="-1">How far can the same instructions travel? <a class="header-anchor" href="#how-far-can-the-same-instructions-travel" aria-label="Permalink to &quot;How far can the same instructions travel?&quot;">​</a></h2><p>A work package is like the operating guide you give a new employee. It says where to get the records, how to compare them, and what to hand back. A guide can tell the worker to open the count sheet. The working environment still has to provide a way to open it. If the guide supplies only commands, the worker needs a terminal to run them.</p><p>MCP is a protocol that connects AI applications with external tools. In this experiment, the worker uses it to call tools that read the register and the count sheet.</p><p>Paradev is an open-source workspace for running multiple AI coding agents in parallel. It comes with guides that tell the AI how to carry out tasks such as looking up its assignments. Those guides originally listed terminal commands only, so a chat application connected to Paradev lacked instructions for using its available tools. <a href="https://github.com/ParadevAI/Paradev" target="_blank" rel="noreferrer">Paradev project overview</a></p><p>Paradev’s change #10267 added MCP instructions wherever an existing tool covered the step. A chat application connected to Paradev’s tools can now follow the guide and call the task-list tool to answer “What tasks are assigned to me?” Steps that still need the terminal are marked as local-only. The author checked tool names and parameters. The change was not tested end to end in Claude.ai, ChatGPT, or Grok. <a href="https://github.com/ParadevAI/Paradev/pull/10267" target="_blank" rel="noreferrer">Paradev #10267: Tool instructions for chat applications without a terminal</a></p><p>That change prompted us to run an equipment-list assignment in CodeFlowMu, a system that organizes digital workers and stores their tasks and reports. We wanted to see how the instructions and the tools actually available shaped what the worker could deliver.</p><h2 id="the-guide-lists-two-tools-the-environment-supplies-one" tabindex="-1">The guide lists two tools. The environment supplies one. <a class="header-anchor" href="#the-guide-lists-two-tools-the-environment-supplies-one" aria-label="Permalink to &quot;The guide lists two tools. The environment supplies one.&quot;">​</a></h2><p>We used Codex to run three AI workers in separate sessions with the same model. Each received an identical assignment. The comparison rules and synthetic inputs stayed the same. We varied the retrieval instructions and the tools actually supplied. All three workers could read the assignment and guide and write a report. The assignments and reports went through the actual CodeFlowMu interfaces, and the completed case was submitted for review.</p><table tabindex="0"><thead><tr><th>Case</th><th>Method described in the guide</th><th>Retrieval tools supplied</th><th>What the worker handed back</th></tr></thead><tbody><tr><td>1</td><td>Command-line steps only</td><td>No terminal and neither retrieval tool</td><td>Read neither record, filed a blocker, and left the assignment open.</td></tr><tr><td>2</td><td>Instructions for both MCP calls</td><td>Register and count-sheet tools</td><td>Read both records, reported <code>D-02</code> absent from the count, and submitted for review.</td></tr><tr><td>3</td><td>Same guide as case 2</td><td>Register tool only</td><td>Recorded the IDs it read, identified the missing count-sheet tool, and left the assignment open.</td></tr></tbody></table><p>In case 2, the worker read both records. You can do the same comparison with the IDs it received.</p><ul><li>Register IDs: <code>D-01</code>, <code>D-02</code>, <code>D-03</code></li><li>Count-sheet IDs: <code>D-01</code>, <code>D-03</code></li></ul><p><code>D-02</code> was registered and did not appear on this count sheet. To determine whether it was missed during a scan, lent out, or lost, the team would need a physical check or another record.</p><figure><picture><source media="(max-width: 580px)" srcset="'+p+'"><img src="'+d+'" alt="Two cases used the same MCP guide. With both tools, the worker reported D-02 absent from the count sheet. With only the register tool, it recorded the IDs it read and the retrieval capability it needed."></picture></figure><p>Cases 2 and 3 used the same guide. The only difference was whether the count-sheet tool was available. The worker in case 3 still retrieved the register. It handed back the three IDs and explained that the environment needed a way to read the count sheet before it could complete the comparison. <strong>It handed back useful unfinished work.</strong> The person responsible now knows which capability to provide and which check remains.</p><h2 id="take-one-assignment-into-the-new-environment" tabindex="-1">Take one assignment into the new environment <a class="header-anchor" href="#take-one-assignment-into-the-new-environment" aria-label="Permalink to &quot;Take one assignment into the new environment&quot;">​</a></h2><p>Use one assignment to check three things in the new environment.</p><ul><li>Can the worker actually retrieve both required records?</li><li>Can you trace the reported discrepancy to specific IDs in the two records?</li><li>If the work stops short, does the report say what the worker read, what remains missing, and what it needs to continue?</li></ul><p>CodeFlowMu stores tasks and reports through FCoP, a file-based coordination protocol. The records let us verify which case submitted a discrepancy report and which two stayed open. Each condition ran once. Installing and running the same package across real working environments remains to be tested.</p><p>Back to case 3. Once the count-sheet tool is available, could a different worker tell what has already been checked and what remains? If the register changes meanwhile, which version should that worker use?</p><p><strong>What does an unfinished assignment need to carry so the next worker can pick up where it left off?</strong></p><h3 id="experiment-materials" tabindex="-1">Experiment materials <a class="header-anchor" href="#experiment-materials" aria-label="Permalink to &quot;Experiment materials&quot;">​</a></h3><ul><li><a href="https://joinwell52-ai.github.io/joinwell52/assets/work-package-portability-20261128/experiment-report.html#english" target="_blank" rel="noopener">Experiment report</a> records the instructions, actual tool conditions, results, and limits.</li><li><a href="https://joinwell52-ai.github.io/joinwell52/assets/work-package-portability-20261128/results.json" target="_blank" rel="noopener">Tool traces and formal report readback</a> show what each worker read, what it handed back, and how the assignment was left.</li></ul>',25))])}const y=n(c,[["render",u]]);export{f as __pageData,y as default};
